            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() || timeout(remaining, &mut worker).await.is_err() {
                worker.abort();
                let _ = timeout(Duration::from_millis(100), &mut worker).await;
            }
        }
    }

